steps.run:
$cargo = rustup which cargo
if ($LASTEXITCODE -ne 0) { throw 'Cargo resolution failed' }
$rustc = rustup which rustc
if ($LASTEXITCODE -ne 0) { throw 'Rustc resolution failed' }
$node = (Get-Command node).Source
python -B tests/native-cli-smoke/run_ci.py --root "$env:GITHUB_WORKSPACE" --head "$env:CLI_SOURCE_SHA" --target "$env:RUNNER_TEMP/private-cli-target" --output "$env:RUNNER_TEMP/private-cli-proof" --node "$node" --cargo "$cargo" --rustc "$rustc"
if ($LASTEXITCODE -ne 0) { throw 'Private CLI proof failed' }

$platform = if ($IsWindows) { 'win32' } else { 'linux' }
python -B tests/native-cli-smoke/verify_ci_receipts.py --root "$env:GITHUB_WORKSPACE" --head "$env:CLI_SOURCE_SHA" --platform "$platform" --output "$env:RUNNER_TEMP/private-cli-proof"
if ($LASTEXITCODE -ne 0) { throw 'Current CLI receipt admission failed' }

$platform = if ($IsWindows) { 'win32' } else { 'linux' }
python -B tests/native-provider-qualification/verify.py --root "$env:GITHUB_WORKSPACE" --head "$env:CLI_SOURCE_SHA" --platform "$platform" --output "$env:RUNNER_TEMP/private-cold-proof"
if ($LASTEXITCODE -ne 0) { throw 'Cold retained receipt admission failed' }

$cargo = rustup which cargo
if ($LASTEXITCODE -ne 0) { throw 'Cargo resolution failed' }
$rustc = rustup which rustc
if ($LASTEXITCODE -ne 0) { throw 'Rustc resolution failed' }
$node = (Get-Command node).Source
python -B tests/native-provider-qualification/corpus/run.py --root "$env:GITHUB_WORKSPACE" --head "$env:CLI_SOURCE_SHA" --target "$env:RUNNER_TEMP/private-cli-target" --output "$env:RUNNER_TEMP/private-fault-corpus-proof" --cargo "$cargo" --rustc "$rustc" --node "$node"
if ($LASTEXITCODE -ne 0) { throw 'Finite retained fault corpus failed' }

$platform = if ($IsWindows) { 'win32' } else { 'linux' }
python -B tests/native-provider-qualification/corpus/verify.py --root "$env:GITHUB_WORKSPACE" --head "$env:CLI_SOURCE_SHA" --platform "$platform" --output "$env:RUNNER_TEMP/private-fault-corpus-proof"
if ($LASTEXITCODE -ne 0) { throw 'Finite retained fault corpus admission failed' }

$cargo = rustup which cargo
if ($LASTEXITCODE -ne 0) { throw 'Cargo resolution failed' }
$rustc = rustup which rustc
if ($LASTEXITCODE -ne 0) { throw 'Rustc resolution failed' }
$node = (Get-Command node).Source
python -B tests/native-provider-qualification/physical/run.py --group vec --root "$env:GITHUB_WORKSPACE" --head "$env:CLI_SOURCE_SHA" --target "$env:RUNNER_TEMP/private-cli-target" --output "$env:RUNNER_TEMP/private-physical-proof" --cargo "$cargo" --rustc "$rustc" --node "$node"
if ($LASTEXITCODE -ne 0) { throw 'Real physical allocation corpus failed' }
